\title{DS-HGCN: A Dual-Stream Hypergraph Convolutional Network for Predicting Student Engagement via Social Contagion}
\titlerunning{Dual-Stream Hypergraph Convolutional Network}

\author{Ziyang Fan\inst{1}~\orcidlink{0000-1111-2222-3333} \and
	Li Tao\inst{1(}\Envelope\inst{)}~\orcidlink{0000-0003-0851-1289} \and
